insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('28107994-79b6-55fc-979a-3a50a8a1ee44','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Bilangan 0–10','buku-matematika-kelas-1-bab-1',1,'A','Buku · Bab 1','dasar','draft',20,'{"summary":"Bab 1 dari 8 — Bilangan 0–10. Bahan ajar berurutan dengan subbab, kegiatan, latihan dan pembahasan. Pelajari bertahap bersama pendamping.","video_url":null,"book_id":"matematika-1-2022","chapter_number":1,"content_kind":"full_chapter","cp_reference":{"document":"046/H/KR/2025","phase":"A","element_ids":["cp2025-matematika-a-1"],"mapping_status":"proposed_mapping","phase_coverage":"partial","reviewed_by":null},"review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal per bab, mengikuti urutan buku pemerintah 2022. Penulisan tersedia; ketepatan pedagogis dan keselarasan CP masih menunggu review guru.","objectives":["Menghubungkan banyak benda dengan lambang bilangan 0–10.","Membandingkan dua kelompok dengan memasangkan benda.","Melanjutkan urutan maju/mundur dan menemukan dua bagian suatu bilangan."],"enrichment":false,"curriculum_note":"Urutan bab mengikuti buku 2022; CP acuan proyek adalah 046/H/KR/2025. Kecukupan CP Fase A lintas kelas 1–2 tetap memerlukan pemetaan guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas I — Dara Retno Wulan dan Rasfaniwaty, 2022; hlm. cetak 1–40","url":"https://repositori.kemendikdasmen.go.id/35868/1/Matematika-BS-KLS-I.pdf#page=13","audience":"student"},{"title":"Buku panduan guru Matematika kelas I, 2022","url":"https://repositori.kemendikdasmen.go.id/35861/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menghubungkan banyak benda dengan lambang bilangan 0–10.\n2. Membandingkan dua kelompok dengan memasangkan benda.\n3. Melanjutkan urutan maju/mundur dan menemukan dua bagian suatu bilangan."},{"type":"text","heading":"Sebelum mulai","body":"Di meja belajar ada pensil, penghapus, dan kertas. Kita dapat mengetahui banyaknya tanpa menebak. Siapkan benda yang cukup besar dan aman untuk dipegang. Hari ini kita belajar menghitung dengan teliti, lalu menggunakan hasil hitungan untuk membandingkan dan menyusun kelompok. Tidak perlu menyelesaikan semua bagian sekaligus; berhentilah setelah satu subbab jika sudah lelah."},{"type":"text","heading":"A. Menghitung dan menulis","body":"Bilangan memberi tahu banyak benda. Letakkan benda berjajar. Sentuh satu benda sambil menyebut satu nama bilangan: satu, dua, tiga, dan seterusnya. Setiap benda disentuh sekali. Nama bilangan terakhir menyatakan banyak seluruh benda. Jika enam tutup botol dipindah menjadi lingkaran, banyaknya tetap enam selama tidak ada yang ditambah atau diambil. Tulisan 6 adalah lambang bilangan enam. Bilangan 0 dibaca nol dan menyatakan tidak ada benda dalam kelompok yang sedang dihitung. Menulis angka perlu latihan gerak tangan; tirukan bentuk angka perlahan, bukan hanya menebak namanya."},{"type":"text","heading":"Contoh bertahap 1","body":"Letakkan 5 balok. Sentuh satu per satu: 1, 2, 3, 4, 5. Ada lima balok, ditulis 5. Pindahkan semua balok ke kotak lain. Kotak semula sekarang berisi 0 balok."},{"type":"tip","body":"Susun 4 benda, hitung sambil menunjuk, lalu tulis bilangannya. Buat sebuah kelompok kosong dan ceritakan artinya."},{"type":"text","heading":"B. Membandingkan banyak benda","body":"Dua kelompok dapat dibandingkan dengan membuat pasangan satu-satu. Pasangkan setiap pensil dengan satu kertas. Jika semuanya berpasangan dan tidak ada yang tersisa, kedua kelompok sama banyak. Jika pensil tersisa, pensil lebih banyak daripada kertas. Jika kertas tersisa, pensil lebih sedikit daripada kertas. Jarak yang renggang atau ukuran benda tidak menentukan banyaknya. Tiga batu besar tetap lebih sedikit daripada lima batu kecil. Hitung kembali bila kamu belum yakin."},{"type":"text","heading":"Contoh bertahap 2","body":"Ada 7 kartu dan 5 penjepit. Pasangkan satu penjepit dengan satu kartu. Dua kartu tidak mendapat pasangan. Kartu lebih banyak; penjepit lebih sedikit."},{"type":"tip","body":"Buat kelompok 6 dan 6 benda. Renggangkan salah satu kelompok. Apakah banyaknya berubah? Jelaskan dengan memasangkan benda."},{"type":"text","heading":"C. Urutan maju dan mundur","body":"Menghitung maju berarti menyebut bilangan dari kecil menuju lebih besar. Setiap langkah menambah satu. Menghitung mundur berarti bergerak ke bilangan sebelumnya; setiap langkah mengurangi satu. Kita boleh mulai dari bilangan selain nol. Urutan membantu menemukan benda berikutnya dan memeriksa apakah ada bilangan yang terlewat. Saat menghitung mundur, gunakan benda atau kartu bilangan agar arah langkah terlihat. Tidak perlu menghitung cepat; yang penting urutannya benar."},{"type":"text","heading":"Contoh bertahap 3","body":"Mulai dari 4 lalu maju tiga langkah: 5, 6, 7. Mulai dari 8 lalu mundur tiga langkah: 7, 6, 5. Bilangan awal tidak dihitung sebagai langkah pertama."},{"type":"tip","body":"Lengkapi 3, 4, __, 6 dan 9, 8, __, 6. Gunakan kartu bilangan untuk memeriksa."},{"type":"text","heading":"D. Menyusun dan mengurai bilangan","body":"Suatu kelompok dapat dipisahkan menjadi dua bagian. Banyak kedua bagian jika digabung kembali sama dengan banyak kelompok semula. Inilah pasangan bilangan. Satu bilangan mempunyai beberapa pasangan. Memindahkan sebuah benda dari bagian kiri ke kanan mengubah banyak tiap bagian, tetapi tidak mengubah jumlah seluruhnya. Bagian boleh kosong: enam benda dapat dipisahkan menjadi enam dan nol. Pemahaman bagian dan keseluruhan akan membantu kita menjumlahkan serta mengurangkan."},{"type":"text","heading":"Contoh bertahap 4","body":"Siapkan 8 benda. Pisahkan menjadi 3 dan 5, lalu gabungkan: tetap 8. Coba 4 dan 4, atau 1 dan 7. Semua merupakan pasangan untuk 8."},{"type":"tip","body":"Cari tiga pasangan berbeda untuk 7 menggunakan benda. Ceritakan bagian kiri, bagian kanan, dan keseluruhannya."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat toko kartu bilangan. Pendamping memilih kartu 0–10, lalu anak menyiapkan banyak benda yang sesuai. Tukar peran. Pilih dua kartu untuk membandingkan kelompok; pilih satu kartu lagi untuk mencari pasangan bilangannya. Gunakan benda besar dan jangan memasukkan benda ke mulut."},{"type":"text","heading":"Rangkuman bab","body":"Satu benda mendapat satu hitungan. Bilangan terakhir menyatakan jumlah. Nol berarti tidak ada benda pada kelompok yang dihitung. Banyak benda dapat dibandingkan dengan pasangan satu-satu. Urutan maju/mundur berubah satu langkah. Bilangan dapat diurai menjadi dua bagian dan disusun kembali."},{"type":"text","heading":"Latihan mandiri","body":"1. Apa perbedaan lambang 0 dan 1 dalam kelompok benda?\n2. Ada 5 sendok dan 3 mangkuk. Kelompok mana lebih banyak?\n3. Lengkapi 6, 7, __, 9.\n4. Lengkapi 5, 4, __, 2.\n5. Tuliskan dua pasangan untuk 6."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Nol menyatakan tidak ada benda; satu menyatakan ada satu benda.\n2. Sendok lebih banyak. Setelah dipasangkan, dua sendok tersisa.\n3. 8, karena urutan maju bertambah satu.\n4. 3, karena urutan mundur berkurang satu.\n5. Misalnya 1 dan 5 serta 2 dan 4. Pasangan lain yang jumlahnya 6 juga benar.","collapsible":true},{"type":"text","heading":"Refleksi belajar","body":"Tunjukkan satu hal yang sekarang dapat kamu lakukan. Jelaskan caranya memakai benda, gambar atau cerita. Bagian mana yang masih perlu bantuan? Kamu boleh kembali ke subbab tersebut sebelum lanjut. Pendamping mencatat cara berpikir dan bantuan yang masih diperlukan, bukan hanya banyak soal yang benar."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jika urutan masih terlewat, batasi dahulu sampai 5 dan pindahkan benda yang sudah dihitung. Jika sudah lancar, minta anak membuktikan jumlah tidak berubah ketika susunan dipindah. Amati cara menghitung dan alasan, bukan hanya jawaban akhir.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('e97b4ce9-0120-5892-b16d-b1b36fbda91c','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Penjumlahan hingga 10','buku-matematika-kelas-1-bab-2',1,'A','Buku · Bab 2','dasar','draft',20,'{"summary":"Bab 2 dari 8 — Penjumlahan hingga 10. Bahan ajar berurutan dengan subbab, kegiatan, latihan dan pembahasan. Pelajari bertahap bersama pendamping.","video_url":null,"book_id":"matematika-1-2022","chapter_number":2,"content_kind":"full_chapter","cp_reference":{"document":"046/H/KR/2025","phase":"A","element_ids":["cp2025-matematika-a-1","cp2025-matematika-a-2"],"mapping_status":"proposed_mapping","phase_coverage":"partial","reviewed_by":null},"review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal per bab, mengikuti urutan buku pemerintah 2022. Penulisan tersedia; ketepatan pedagogis dan keselarasan CP masih menunggu review guru.","objectives":["Menceritakan penjumlahan sebagai menggabungkan atau menambah.","Menjumlahkan dengan benda, gambar, dan hitung maju hingga 10.","Menuliskan kalimat matematika dan menjawab soal cerita."],"enrichment":false,"curriculum_note":"Urutan bab mengikuti buku 2022; CP acuan proyek adalah 046/H/KR/2025. Kecukupan CP Fase A lintas kelas 1–2 tetap memerlukan pemetaan guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas I — Dara Retno Wulan dan Rasfaniwaty, 2022; hlm. cetak 41–74","url":"https://repositori.kemendikdasmen.go.id/35868/1/Matematika-BS-KLS-I.pdf#page=53","audience":"student"},{"title":"Buku panduan guru Matematika kelas I, 2022","url":"https://repositori.kemendikdasmen.go.id/35861/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menceritakan penjumlahan sebagai menggabungkan atau menambah.\n2. Menjumlahkan dengan benda, gambar, dan hitung maju hingga 10.\n3. Menuliskan kalimat matematika dan menjawab soal cerita."},{"type":"text","heading":"Sebelum mulai","body":"Sebuah kelompok bisa menjadi lebih banyak ketika benda lain datang. Kita memakai penjumlahan untuk mengetahui banyak seluruhnya. Siapkan dua warna kartu atau balok. Warna berbeda membantu melihat dua bagian yang akan digabung. Setelah memahami dengan benda, kita dapat memakai gambar dan lambang bilangan."},{"type":"text","heading":"A. Cerita menggabungkan","body":"Penjumlahan digunakan ketika dua bagian digabung menjadi keseluruhan atau ketika suatu kelompok mendapat tambahan. Banyak bagian pertama dan kedua perlu diketahui. Tanda + dibaca tambah; tanda = berarti kedua sisi menyatakan nilai yang sama. Lambang ini bukan perintah untuk selalu menulis bilangan yang lebih besar. Jumlah seluruh benda ditulis di sebelah kanan tanda sama dengan dalam bentuk yang biasa kita gunakan. Cerita perlu dipahami sebelum memilih operasi."},{"type":"text","heading":"Contoh bertahap 1","body":"Ada 3 kartu hijau dan 5 kartu kuning. Gabungkan lalu hitung semuanya. Ada 8 kartu. Kalimatnya 3 + 5 = 8. Delapan adalah banyak seluruh kartu."},{"type":"tip","body":"Buat cerita berbeda untuk 2 + 4. Tunjukkan kedua bagian dan keseluruhannya dengan benda."},{"type":"text","heading":"B. Strategi menjumlahkan","body":"Cara pertama ialah menghitung semua benda setelah digabung. Cara kedua ialah menghitung maju dari salah satu bilangan. Misalnya mulai dari lima, lalu lakukan dua langkah untuk menambah dua. Jangan menyebut bilangan awal sebagai satu langkah tambahan. Kamu juga dapat menggambar lingkaran atau memakai bingkai sepuluh: dua baris yang masing-masing berisi lima tempat. Cara yang berbeda dapat menghasilkan jumlah yang sama. Periksa dengan benda bila hasilnya berbeda. Menukar urutan dua bagian tidak mengubah keseluruhan."},{"type":"text","heading":"Contoh bertahap 2","body":"Untuk 6 + 3, mulai di 6. Tiga langkah berikutnya adalah 7, 8, 9, sehingga hasilnya 9. Periksa dengan enam balok dan tiga balok. Untuk 0 + 4, tidak ada benda pada bagian pertama; hasilnya 4."},{"type":"tip","body":"Hitung 4 + 3 dengan dua cara. Coba pula 3 + 4. Apa yang sama dari kedua hasilnya?"},{"type":"text","heading":"C. Menyelesaikan soal cerita","body":"Saat membaca soal cerita, tanyakan: benda apa yang dihitung, apa yang sudah diketahui, dan apa yang ditanyakan? Gambarkan dua kelompok atau peragakan ceritanya. Pilih penjumlahan jika mencari gabungan atau banyak setelah mendapat tambahan. Tulis kalimat matematika, hitung, lalu tulis jawaban dengan nama bendanya. Terakhir, periksa apakah jawaban masuk akal. Tidak semua cerita yang panjang sulit; ambil informasi yang diperlukan satu per satu."},{"type":"text","heading":"Contoh bertahap 3","body":"Di rak ada 4 buku. Sari menaruh 5 buku lagi. Diketahui empat buku semula dan tambahan lima buku. Ditanya banyak buku sekarang. Kalimatnya 4 + 5 = 9. Jadi sekarang ada 9 buku; hasil lebih banyak daripada jumlah semula."},{"type":"tip","body":"Ada 2 anak duduk dan 6 anak datang. Berapa anak sekarang? Gambar ceritanya, lalu tulis kalimat matematika dan jawaban lengkap."},{"type":"text","heading":"Kegiatan penerapan","body":"Bermain keranjang gabung. Siapkan dua wadah dan paling banyak sepuluh benda. Pendamping memasukkan benda ke tiap wadah, lalu anak menceritakan dan menuliskan penjumlahannya. Gabungkan untuk memeriksa. Pada putaran berikutnya, salah satu wadah boleh kosong. Anak boleh memilih strategi menghitung semua atau menghitung maju."},{"type":"text","heading":"Rangkuman bab","body":"Penjumlahan mencari keseluruhan atau banyak setelah mendapat tambahan. Gunakan benda, gambar, atau hitung maju. Tanda sama dengan menyatakan kesamaan nilai. Nol tidak menambah banyak benda. Jawaban soal cerita menyebut bilangan sekaligus nama benda yang dihitung."},{"type":"text","heading":"Latihan mandiri","body":"1. Hitung 3 + 4.\n2. Hitung 5 + 0.\n3. Ada 6 pita, lalu mendapat 2 pita. Berapa semuanya?\n4. Jelaskan dua langkah hitung maju dari 7.\n5. Buat gambar untuk 1 + 8 dan tulis hasilnya."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 7; gabungkan tiga dan empat benda.\n2. 5; tidak ada tambahan benda.\n3. 8 pita; 6 + 2 = 8.\n4. 8 lalu 9, sehingga 7 + 2 = 9.\n5. Satu benda dan delapan benda menjadi sembilan; 1 + 8 = 9.","collapsible":true},{"type":"text","heading":"Refleksi belajar","body":"Tunjukkan satu hal yang sekarang dapat kamu lakukan. Jelaskan caranya memakai benda, gambar atau cerita. Bagian mana yang masih perlu bantuan? Kamu boleh kembali ke subbab tersebut sebelum lanjut. Pendamping mencatat cara berpikir dan bantuan yang masih diperlukan, bukan hanya banyak soal yang benar."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jika anak menghitung bilangan awal sebagai langkah tambahan, tandai posisi awal dan gerakkan jari sesudah menyebut langkah. Beri kesempatan memakai benda selama perlu. Pengayaan: cari beberapa penjumlahan yang hasilnya 10 dan jelaskan mengapa semuanya benar.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('8660d718-8a1b-5d40-9bbb-1b3433b70f78','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Pengurangan hingga 10','buku-matematika-kelas-1-bab-3',1,'A','Buku · Bab 3','dasar','draft',20,'{"summary":"Bab 3 dari 8 — Pengurangan hingga 10. Bahan ajar berurutan dengan subbab, kegiatan, latihan dan pembahasan. Pelajari bertahap bersama pendamping.","video_url":null,"book_id":"matematika-1-2022","chapter_number":3,"content_kind":"full_chapter","cp_reference":{"document":"046/H/KR/2025","phase":"A","element_ids":["cp2025-matematika-a-1","cp2025-matematika-a-2"],"mapping_status":"proposed_mapping","phase_coverage":"partial","reviewed_by":null},"review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal per bab, mengikuti urutan buku pemerintah 2022. Penulisan tersedia; ketepatan pedagogis dan keselarasan CP masih menunggu review guru.","objectives":["Menjelaskan sisa sebagai hasil pengurangan.","Mengurangkan dengan benda, gambar dan hitung mundur hingga 10.","Memakai hubungan penjumlahan/pengurangan untuk memeriksa jawaban."],"enrichment":false,"curriculum_note":"Urutan bab mengikuti buku 2022; CP acuan proyek adalah 046/H/KR/2025. Kecukupan CP Fase A lintas kelas 1–2 tetap memerlukan pemetaan guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas I — Dara Retno Wulan dan Rasfaniwaty, 2022; hlm. cetak 75–114","url":"https://repositori.kemendikdasmen.go.id/35868/1/Matematika-BS-KLS-I.pdf#page=87","audience":"student"},{"title":"Buku panduan guru Matematika kelas I, 2022","url":"https://repositori.kemendikdasmen.go.id/35861/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan sisa sebagai hasil pengurangan.\n2. Mengurangkan dengan benda, gambar dan hitung mundur hingga 10.\n3. Memakai hubungan penjumlahan/pengurangan untuk memeriksa jawaban."},{"type":"text","heading":"Sebelum mulai","body":"Kelompok dapat menjadi lebih sedikit ketika sebagian benda diambil. Kita perlu membedakan banyak semula, banyak yang diambil, dan sisa. Siapkan sepuluh kartu yang mudah dipindahkan. Dalam bab ini, semua cerita mengambil benda memiliki banyak yang diambil tidak melebihi banyak semula."},{"type":"text","heading":"A. Cerita mengambil dan mencari sisa","body":"Pada cerita mengambil, pengurangan mencari banyak yang masih tinggal. Tanda − dibaca kurang. Bilangan sebelum tanda kurang menunjukkan banyak semula, sedangkan bilangan setelahnya menunjukkan banyak yang diambil. Sisa dihitung dari benda yang belum dipindahkan. Memindahkan benda ke wadah lain membantu agar benda yang sudah diambil tidak terhitung lagi. Jika semua benda diambil, sisanya nol. Jika tidak ada yang diambil, banyaknya tetap."},{"type":"text","heading":"Contoh bertahap 1","body":"Ada 9 kartu di meja. Empat kartu dimasukkan ke kotak. Hitung lima kartu yang masih di meja: 9 − 4 = 5. Lima adalah sisa, bukan banyak kartu yang dipindah."},{"type":"tip","body":"Peragakan 7 − 2. Sebutkan banyak semula, yang diambil, dan sisanya."},{"type":"text","heading":"B. Strategi mengurangkan","body":"Pengurangan dapat dilakukan dengan mengambil benda, mencoret sebagian gambar, atau menghitung mundur. Pada gambar, buat dahulu semua benda, lalu beri tanda pada benda yang diambil dan hitung yang tidak ditandai. Saat menghitung mundur, mulai dari banyak semula dan lakukan sebanyak langkah yang dikurangkan. Satu langkah dilakukan ke bilangan sebelumnya. Kamu boleh memakai garis bilangan yang dibuat di kertas. Gunakan cara konkret dahulu jika urutan mundur belum lancar."},{"type":"text","heading":"Contoh bertahap 2","body":"Untuk 8 − 3, mulai dari 8 lalu mundur: 7, 6, 5. Ada tiga langkah, jadi hasilnya 5. Untuk 6 − 6, keenam benda diambil sehingga sisa 0."},{"type":"tip","body":"Gambar enam lingkaran, coret satu, lalu hitung sisanya. Periksa 6 − 1 dengan satu langkah mundur."},{"type":"text","heading":"C. Hubungan dengan penjumlahan","body":"Penjumlahan dan pengurangan menghubungkan bagian dengan keseluruhan. Jika tiga dan empat menjadi tujuh, mengambil tiga dari tujuh menyisakan empat. Hubungan ini membantu memeriksa jawaban. Ketika jawaban pengurangan digabung kembali dengan bagian yang diambil, hasilnya harus sama dengan banyak semula. Urutan pengurangan tidak boleh ditukar sesuka hati seperti penjumlahan. Cerita tujuh benda diambil dua berbeda dari dua benda diambil tujuh pada bilangan yang sedang kita pelajari."},{"type":"text","heading":"Contoh bertahap 3","body":"Diketahui 2 + 6 = 8. Maka 8 − 2 = 6 dan 8 − 6 = 2. Periksa 8 − 2 = 6 dengan menjumlahkan sisa enam dan yang diambil dua: 6 + 2 = 8."},{"type":"tip","body":"Jika 4 + 5 = 9, buat dua kalimat pengurangan yang berkaitan. Gunakan sembilan benda untuk memeriksa."},{"type":"text","heading":"D. Soal cerita pengurangan","body":"Baca kejadian sebelum memilih operasi. Cari banyak semula dan perubahan yang terjadi. Jika sebagian benda dibagikan atau dipindahkan, peragakan bagian itu lalu tentukan sisa. Tuliskan kalimat matematika dan jawaban dengan nama benda. Periksa sisa tidak lebih besar daripada banyak semula pada cerita mengambil. Kata tertentu tidak selalu cukup menentukan operasi; pahami apa yang terjadi dan apa yang ditanyakan."},{"type":"text","heading":"Contoh bertahap 4","body":"Raka memiliki 10 lembar kertas. Ia memakai 3 lembar. Banyak semula sepuluh, yang dipakai tiga, dan yang dicari adalah sisa: 10 − 3 = 7. Jadi kertas yang belum dipakai ada 7 lembar. Periksa: tujuh yang tersisa dan tiga yang dipakai berjumlah sepuluh."},{"type":"tip","body":"Ada 8 mangga. Dua mangga diberikan kepada tetangga. Berapa mangga yang masih ada? Jelaskan dengan gambar."},{"type":"text","heading":"Kegiatan penerapan","body":"Permainan cerita sisa: susun paling banyak sepuluh benda. Anak menutup mata sebentar sementara pendamping memindahkan sebagian benda ke wadah yang tetap terlihat. Anak menyebut banyak semula, banyak dipindah dan sisa, lalu menulis pengurangannya. Tukar peran. Hitung kembali seluruh benda setelah digabung untuk mengecek."},{"type":"text","heading":"Rangkuman bab","body":"Pengurangan pada cerita mengambil mencari sisa. Gunakan benda, gambar atau hitung mundur. Mengambil nol tidak mengubah banyak; mengambil semuanya menghasilkan nol. Penjumlahan dapat memeriksa hasil pengurangan. Cerita dan nama benda membantu menjelaskan arti jawaban."},{"type":"text","heading":"Latihan mandiri","body":"1. Hitung 7 − 3.\n2. Hitung 5 − 5.\n3. Hitung 9 − 0.\n4. Ada 10 balon. Dua balon dibawa pulang. Berapa sisanya?\n5. Jika 3 + 6 = 9, tulis dua pengurangan yang berkaitan."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 4, karena dari tujuh benda diambil tiga.\n2. 0, karena semua lima benda diambil.\n3. 9, karena tidak ada benda yang diambil.\n4. 8 balon; 10 − 2 = 8.\n5. 9 − 3 = 6 dan 9 − 6 = 3.","collapsible":true},{"type":"text","heading":"Refleksi belajar","body":"Tunjukkan satu hal yang sekarang dapat kamu lakukan. Jelaskan caranya memakai benda, gambar atau cerita. Bagian mana yang masih perlu bantuan? Kamu boleh kembali ke subbab tersebut sebelum lanjut. Pendamping mencatat cara berpikir dan bantuan yang masih diperlukan, bukan hanya banyak soal yang benar."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Bila anak mengurangkan dengan menghitung benda yang dipindah sebagai sisa, pisahkan tempat kedua kelompok dan beri label “diambil” serta “tinggal”. Pengayaan: berikan sisa dan banyak yang diambil, lalu anak mencari banyak semula dengan penjumlahan.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('611d0560-6645-5c9c-b15f-2869c35c3b7a','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Bentuk di sekitar kita','buku-matematika-kelas-1-bab-4',1,'A','Buku · Bab 4','dasar','draft',20,'{"summary":"Bab 4 dari 8 — Bentuk di sekitar kita. Bahan ajar berurutan dengan subbab, kegiatan, latihan dan pembahasan. Pelajari bertahap bersama pendamping.","video_url":null,"book_id":"matematika-1-2022","chapter_number":4,"content_kind":"full_chapter","cp_reference":{"document":"046/H/KR/2025","phase":"A","element_ids":["cp2025-matematika-a-4"],"mapping_status":"proposed_mapping","phase_coverage":"partial","reviewed_by":null},"review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal per bab, mengikuti urutan buku pemerintah 2022. Penulisan tersedia; ketepatan pedagogis dan keselarasan CP masih menunggu review guru.","objectives":["Mengenali ciri bentuk datar pada benda sekitar.","Mengelompokkan benda dengan satu aturan yang jelas.","Menyusun dan mengurai bentuk sederhana."],"enrichment":false,"curriculum_note":"Urutan bab mengikuti buku 2022; CP acuan proyek adalah 046/H/KR/2025. Kecukupan CP Fase A lintas kelas 1–2 tetap memerlukan pemetaan guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas I — Dara Retno Wulan dan Rasfaniwaty, 2022; hlm. cetak 115–144","url":"https://repositori.kemendikdasmen.go.id/35868/1/Matematika-BS-KLS-I.pdf#page=127","audience":"student"},{"title":"Buku panduan guru Matematika kelas I, 2022","url":"https://repositori.kemendikdasmen.go.id/35861/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Mengenali ciri bentuk datar pada benda sekitar.\n2. Mengelompokkan benda dengan satu aturan yang jelas.\n3. Menyusun dan mengurai bentuk sederhana."},{"type":"text","heading":"Sebelum mulai","body":"Permukaan buku, rambu, dan tutup wadah mempunyai bentuk yang dapat diamati. Kita belajar dari cirinya, bukan hanya dari nama atau warnanya. Siapkan potongan kertas yang aman dan beberapa benda di rumah. Benda nyata mempunyai ketebalan; pada bab ini kita terutama mengamati bentuk permukaan atau jejaknya."},{"type":"text","heading":"A. Mendeskripsikan bentuk","body":"Segitiga mempunyai tiga sisi lurus dan tiga sudut. Bentuk segi empat mempunyai empat sisi; persegi dan persegi panjang termasuk kelompok ini. Persegi memiliki empat sisi sama panjang dan sudut siku-siku. Lingkaran dibatasi garis lengkung, sehingga tidak memiliki sisi lurus atau titik sudut seperti segitiga. Putarlah potongan bentuk: segitiga tetap segitiga walaupun ujungnya menghadap ke bawah. Warna dan arah letak tidak mengubah jumlah sisi. Tidak semua segi empat adalah persegi; perhatikan panjang sisi dan sudutnya."},{"type":"text","heading":"Contoh bertahap 1","body":"Sebuah potongan kertas memiliki tiga sisi lurus. Walaupun dicat merah atau diputar, bentuknya tetap segitiga. Permukaan muka kotak tisu mungkin berbentuk persegi panjang, tetapi seluruh kotaknya bukan bangun datar."},{"type":"tip","body":"Amati tiga benda di sekitar. Ceritakan bentuk permukaan yang kamu lihat dan ciri yang mendukung jawabanmu."},{"type":"text","heading":"B. Mengelompokkan benda","body":"Mengelompokkan berarti menempatkan benda yang memenuhi aturan yang sama bersama-sama. Kita boleh mengelompokkan berdasarkan bentuk, warna, atau ukuran, tetapi harus menyebut aturan yang sedang dipakai. Jika aturannya bentuk, segitiga merah dan segitiga biru berada dalam kelompok sama. Sebuah benda dapat berpindah kelompok ketika aturannya diubah. Jangan mencampur aturan tanpa penjelasan, karena orang lain akan sulit memahami kelompokmu."},{"type":"text","heading":"Contoh bertahap 2","body":"Ada lingkaran kuning, lingkaran hijau, dan persegi kuning. Jika aturannya bentuk, kedua lingkaran bersama. Jika aturannya warna, lingkaran kuning bersama persegi kuning. Kedua cara benar karena aturannya berbeda."},{"type":"tip","body":"Kelompokkan enam potongan kertas menurut bentuk. Setelah itu, ubah aturan menjadi warna. Jelaskan benda mana yang berpindah kelompok."},{"type":"text","heading":"C. Menyusun dan mengurai bentuk","body":"Beberapa bentuk kecil dapat disusun menjadi bentuk lain tanpa saling menumpuk. Kegiatan ini disebut menyusun. Sebaliknya, satu bentuk dapat dipisahkan menjadi bagian-bagian; inilah mengurai. Bagian dapat diputar atau digeser sebelum disusun. Amati batas luar hasil susunan untuk mengenal bentuk baru. Percobaan dapat memiliki lebih dari satu jawaban. Gunakan potongan kertas yang disiapkan pendamping agar aman; tidak perlu memakai alat potong sendiri."},{"type":"text","heading":"Contoh bertahap 3","body":"Dua segitiga siku-siku yang sama, masing-masing berasal dari satu persegi yang dibelah diagonal, dapat disusun kembali menjadi persegi. Satu persegi panjang dapat ditutup oleh dua persegi sama besar jika panjangnya dua kali lebarnya. Buktikan dengan potongan yang pas, bukan dengan menumpuk."},{"type":"tip","body":"Susun dua atau tiga potongan menjadi gambar rumah atau perahu. Ceritakan bentuk yang dipakai dan apakah ada bagian yang bertumpuk."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat galeri bentuk. Pilih enam benda, gambar bentuk permukaan yang diamati, lalu kelompokkan hasil gambar. Jelaskan aturan kelompok. Gunakan potongan kertas untuk menyusun satu gambar baru. Pendamping menilai cara anak menyebut ciri, mengelompokkan dengan konsisten, dan menjelaskan susunan; kerapian gambar bukan satu-satunya penilaian."},{"type":"text","heading":"Rangkuman bab","body":"Bentuk dikenali dari cirinya. Warna dan putaran tidak mengubah bentuk. Aturan pengelompokan harus jelas. Bentuk kecil dapat disusun menjadi bentuk lain, dan satu bentuk dapat diurai menjadi beberapa bagian. Bentuk permukaan benda dibedakan dari keseluruhan benda ruang."},{"type":"text","heading":"Latihan mandiri","body":"1. Berapa sisi lurus segitiga?\n2. Apakah segitiga berubah menjadi lingkaran jika diputar?\n3. Jika aturan kelompok adalah warna, apakah dua bentuk merah boleh bersama?\n4. Apa bedanya menyusun dan mengurai bentuk?\n5. Gambarlah satu benda dan sebutkan bentuk permukaannya."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Tiga sisi lurus.\n2. Tidak; ciri sisi dan sudutnya tetap.\n3. Boleh, walaupun bentuknya berbeda, karena aturannya warna.\n4. Menyusun menggabungkan bagian; mengurai memisahkan satu bentuk menjadi bagian.\n5. Jawaban beragam. Misalnya permukaan depan buku berbentuk persegi panjang; alasan perlu sesuai pengamatan.","collapsible":true},{"type":"text","heading":"Refleksi belajar","body":"Tunjukkan satu hal yang sekarang dapat kamu lakukan. Jelaskan caranya memakai benda, gambar atau cerita. Bagian mana yang masih perlu bantuan? Kamu boleh kembali ke subbab tersebut sebelum lanjut. Pendamping mencatat cara berpikir dan bantuan yang masih diperlukan, bukan hanya banyak soal yang benar."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Mulai dengan dua bentuk yang sangat berbeda. Ajak anak menelusuri batasnya memakai jari. Gunakan potongan dengan ukuran dan warna serupa agar anak fokus pada bentuk. Pengayaan: temukan lebih dari satu cara menyusun potongan yang sama dan jelaskan cirinya.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('2461d450-1057-5a1e-86ce-84abc95edcf0','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Bilangan 11–20','buku-matematika-kelas-1-bab-5',1,'A','Buku · Bab 5','dasar','draft',20,'{"summary":"Bab 5 dari 8 — Bilangan 11–20. Bahan ajar berurutan dengan subbab, kegiatan, latihan dan pembahasan. Pelajari bertahap bersama pendamping.","video_url":null,"book_id":"matematika-1-2022","chapter_number":5,"content_kind":"full_chapter","cp_reference":{"document":"046/H/KR/2025","phase":"A","element_ids":["cp2025-matematika-a-1"],"mapping_status":"proposed_mapping","phase_coverage":"partial","reviewed_by":null},"review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal per bab, mengikuti urutan buku pemerintah 2022. Penulisan tersedia; ketepatan pedagogis dan keselarasan CP masih menunggu review guru.","objectives":["Menghitung dan menulis bilangan 11–20.","Menggunakan satu kelompok sepuluh untuk menjelaskan puluhan dan satuan.","Mengurutkan serta membandingkan bilangan hingga 20."],"enrichment":false,"curriculum_note":"Urutan bab mengikuti buku 2022; CP acuan proyek adalah 046/H/KR/2025. Kecukupan CP Fase A lintas kelas 1–2 tetap memerlukan pemetaan guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas I — Dara Retno Wulan dan Rasfaniwaty, 2022; hlm. cetak 145–174","url":"https://repositori.kemendikdasmen.go.id/35868/1/Matematika-BS-KLS-I.pdf#page=157","audience":"student"},{"title":"Buku panduan guru Matematika kelas I, 2022","url":"https://repositori.kemendikdasmen.go.id/35861/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menghitung dan menulis bilangan 11–20.\n2. Menggunakan satu kelompok sepuluh untuk menjelaskan puluhan dan satuan.\n3. Mengurutkan serta membandingkan bilangan hingga 20."},{"type":"text","heading":"Sebelum mulai","body":"Menghitung banyak benda lebih mudah jika sebagian dikelompokkan menjadi sepuluh. Siapkan dua bingkai sepuluh atau dua baris tempat benda yang masing-masing memuat sepuluh. Kita akan membaca lambang bilangan, mencari bilangan sebelum dan sesudah, lalu membandingkan jumlahnya. Gunakan benda berukuran aman dan hentikan kegiatan bila perlu istirahat."},{"type":"text","heading":"A. Menghitung dan menulis 11–20","body":"Sesudah sepuluh, urutannya sebelas, dua belas, tiga belas, empat belas, lima belas, enam belas, tujuh belas, delapan belas, sembilan belas, lalu dua puluh. Hitung setiap benda sekali, kemudian cocokkan jumlahnya dengan lambang bilangan. Angka 1 dan 5 yang ditulis bersebelahan membentuk bilangan 15, dibaca lima belas; bukan dua jumlah yang berdiri sendiri. Susunan benda dapat berubah tanpa mengubah banyaknya. Memindahkan benda yang sudah dihitung ke tempat lain membantu mencegah hitungan ganda."},{"type":"text","heading":"Contoh bertahap 1","body":"Isi satu bingkai dengan sepuluh benda, lalu letakkan tiga benda lagi. Hitung 10, 11, 12, 13. Ada tiga belas benda, ditulis 13. Menghitung semua dari satu juga menghasilkan tiga belas."},{"type":"tip","body":"Siapkan 17 benda. Susun sepuluh pada satu tempat, sisanya pada tempat lain. Baca dan tulis bilangannya."},{"type":"text","heading":"B. Urutan maju dan mundur","body":"Urutan maju hingga 20 tetap bertambah satu setiap langkah. Urutan mundur berkurang satu. Kamu boleh melewati batas sepuluh: maju dari 9 menjadi 10 lalu 11; mundur dari 12 menjadi 11 lalu 10. Untuk mencari bilangan di antara dua bilangan, lihat urutan lengkap. Pada kegiatan melangkah, bilangan awal adalah posisi mulai, bukan langkah tambahan."},{"type":"text","heading":"Contoh bertahap 2","body":"Maju tiga langkah dari 12: 13, 14, 15. Mundur dua langkah dari 16: 15, 14. Bilangan di antara 17 dan 19 adalah 18."},{"type":"tip","body":"Lengkapi 14, 15, __, 17 dan 20, 19, __, 17. Jelaskan arah hitungmu."},{"type":"text","heading":"C. Puluhan dan satuan","body":"Sepuluh satuan dapat dikelompokkan menjadi satu puluhan. Bilangan 14 terdiri atas satu puluhan dan empat satuan: 10 + 4. Pada tulisan 14, angka 1 berada di tempat puluhan dan angka 4 di tempat satuan. Nilai angka bergantung pada tempatnya. Bilangan 20 terdiri atas dua puluhan dan nol satuan. Ini berarti tidak ada satuan lepas setelah dua kelompok sepuluh terbentuk, bukan berarti tidak ada benda sama sekali."},{"type":"text","heading":"Contoh bertahap 3","body":"Buat satu kelompok berisi sepuluh benda dan delapan benda lepas. Banyaknya 18: satu puluhan dan delapan satuan. Untuk 20, buat dua kelompok sepuluh; satuan lepasnya nol."},{"type":"tip","body":"Tunjukkan 12 dan 19 dengan kelompok sepuluh. Sebutkan banyak puluhan dan satuan pada masing-masing bilangan."},{"type":"text","heading":"D. Membandingkan bilangan","body":"Untuk membandingkan dua bilangan, kamu dapat memasangkan benda atau melihat kelompok puluhan dan satuannya. Jika kedua kelompok mempunyai satu puluhan, bandingkan satuan lepasnya. Lebih banyak satuan berarti lebih besar. Ketika membandingkan 19 dan 20, perhatikan bahwa 20 mempunyai dua puluhan, sehingga lebih besar walaupun angka satuannya nol. Jarak letak atau ukuran benda tidak menentukan jumlahnya."},{"type":"text","heading":"Contoh bertahap 4","body":"Bandingkan 16 dan 13. Keduanya memiliki satu puluhan. Enam satuan lebih banyak daripada tiga satuan, jadi 16 lebih besar. Urutan dari kecil adalah 13 lalu 16."},{"type":"tip","body":"Urutkan 11, 18, dan 15 dari paling sedikit ke paling banyak. Periksa dengan benda atau kartu bilangan."},{"type":"text","heading":"Kegiatan penerapan","body":"Buat kantong puluhan dengan kertas: satu kantong menampung sepuluh potongan besar. Pendamping menyebut bilangan 11–20 dan anak menunjukkan kantong serta satuan lepas yang diperlukan. Pilih dua bilangan dan bandingkan. Anak lalu menyebut bilangan sebelumnya dan sesudahnya. Pendamping boleh membantu menulis angka."},{"type":"text","heading":"Rangkuman bab","body":"Bilangan 11–19 tersusun dari satu puluhan dan beberapa satuan; 20 mempunyai dua puluhan. Urutan maju dan mundur tetap berubah satu. Perbandingan dilakukan berdasarkan banyak benda atau nilai tempat, bukan ukuran tulisan angka."},{"type":"text","heading":"Latihan mandiri","body":"1. Tuliskan bilangan lima belas.\n2. Ada satu puluhan dan enam satuan. Berapa bilangannya?\n3. Berapa puluhan dan satuan pada 20?\n4. Bilangan sebelum 13 adalah berapa?\n5. Mana lebih besar: 17 atau 14? Jelaskan."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 15.\n2. 16, karena 10 + 6 = 16.\n3. Dua puluhan dan nol satuan lepas.\n4. 12, satu langkah mundur dari 13.\n5. 17; puluhannya sama, tetapi tujuh satuan lebih banyak daripada empat.","collapsible":true},{"type":"text","heading":"Refleksi belajar","body":"Tunjukkan satu hal yang sekarang dapat kamu lakukan. Jelaskan caranya memakai benda, gambar atau cerita. Bagian mana yang masih perlu bantuan? Kamu boleh kembali ke subbab tersebut sebelum lanjut. Pendamping mencatat cara berpikir dan bantuan yang masih diperlukan, bukan hanya banyak soal yang benar."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jika anak menukar lambang 12 dengan 21, kembali ke satu kelompok sepuluh dan dua satuan, lalu tunjuk posisi tiap angka. Tidak perlu memperkenalkan operasi puluhan lebih besar dahulu. Pengayaan: minta anak menjelaskan mengapa 20 lebih besar daripada 19 meskipun angka satuannya nol.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('1cdbfb73-85a6-570a-aa0e-c49cfc5098d1','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Tambah dan kurang hingga 20','buku-matematika-kelas-1-bab-6',1,'A','Buku · Bab 6','dasar','draft',20,'{"summary":"Bab 6 dari 8 — Tambah dan kurang hingga 20. Bahan ajar berurutan dengan subbab, kegiatan, latihan dan pembahasan. Pelajari bertahap bersama pendamping.","video_url":null,"book_id":"matematika-1-2022","chapter_number":6,"content_kind":"full_chapter","cp_reference":{"document":"046/H/KR/2025","phase":"A","element_ids":["cp2025-matematika-a-1","cp2025-matematika-a-2"],"mapping_status":"proposed_mapping","phase_coverage":"partial","reviewed_by":null},"review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal per bab, mengikuti urutan buku pemerintah 2022. Penulisan tersedia; ketepatan pedagogis dan keselarasan CP masih menunggu review guru.","objectives":["Menjelaskan lebih banyak, lebih sedikit dan selisih.","Menjumlahkan serta mengurangkan bilangan dengan hasil hingga 20.","Memilih strategi dan memeriksa jawaban menggunakan model atau operasi kebalikan."],"enrichment":false,"curriculum_note":"Urutan bab mengikuti buku 2022; CP acuan proyek adalah 046/H/KR/2025. Kecukupan CP Fase A lintas kelas 1–2 tetap memerlukan pemetaan guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas I — Dara Retno Wulan dan Rasfaniwaty, 2022; hlm. cetak 175–196","url":"https://repositori.kemendikdasmen.go.id/35868/1/Matematika-BS-KLS-I.pdf#page=187","audience":"student"},{"title":"Buku panduan guru Matematika kelas I, 2022","url":"https://repositori.kemendikdasmen.go.id/35861/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Menjelaskan lebih banyak, lebih sedikit dan selisih.\n2. Menjumlahkan serta mengurangkan bilangan dengan hasil hingga 20.\n3. Memilih strategi dan memeriksa jawaban menggunakan model atau operasi kebalikan."},{"type":"text","heading":"Sebelum mulai","body":"Kita sudah mengenal dua puluh dan bagian-bagiannya. Sekarang gunakan pengetahuan itu untuk membandingkan serta menghitung perubahan banyak benda. Kerjakan dengan kartu atau bingkai sepuluh sebelum berhitung tanpa benda. Sebagian latihan pada materi ini berakhir tepat di 20 sebagai perluasan terbatas dalam rentang bab; pelajari setelah operasi dengan hasil di bawah 20 dipahami."},{"type":"text","heading":"A. Lebih banyak, lebih sedikit, dan selisih","body":"Lebih banyak dan lebih sedikit menyatakan hubungan dua jumlah. Selisih menjelaskan berapa perbedaannya. Pasangkan benda satu-satu: bagian yang tidak mendapat pasangan menunjukkan selisih. Kita dapat mencari selisih dengan mengurangkan jumlah yang lebih kecil dari yang lebih besar. Jangan menjumlahkan kedua kelompok ketika yang ditanya perbedaannya. Sebutkan kelompok yang dibandingkan agar jawaban jelas."},{"type":"text","heading":"Contoh bertahap 1","body":"Dina memiliki 14 kartu dan Bayu 11 kartu. Pasangkan sebelas kartu mereka. Tiga kartu Dina tersisa tanpa pasangan. Dina mempunyai tiga kartu lebih banyak; Bayu tiga kartu lebih sedikit. Selisihnya 14 − 11 = 3."},{"type":"tip","body":"Bandingkan 13 benda dan 9 benda. Peragakan pasangan, lalu jelaskan kelompok yang lebih banyak dan selisihnya."},{"type":"text","heading":"B. Penjumlahan hingga 20","body":"Penjumlahan hingga 20 dapat dilakukan dengan menghitung maju atau membuat sepuluh dahulu. Strategi membuat sepuluh memakai pasangan bilangan. Jika ada delapan benda dan tambahan lima, dua dari tambahan itu melengkapi delapan menjadi sepuluh. Tambahan masih tersisa tiga, sehingga keseluruhannya tiga belas. Memisahkan tambahan tidak mengubah jumlah benda; hanya memudahkan menghitung. Tuliskan langkah yang dapat kamu jelaskan, bukan sekadar menghafal hasilnya."},{"type":"text","heading":"Contoh bertahap 2","body":"Hitung 9 + 6. Pisahkan 6 menjadi 1 dan 5. Gabungkan 9 dengan 1 menjadi 10, kemudian tambah 5 sehingga 15. Periksa dengan lima belas benda atau enam langkah maju dari 9."},{"type":"tip","body":"Selesaikan 7 + 5 dengan melengkapi sepuluh. Jelaskan bagaimana kamu memisahkan bilangan 5."},{"type":"text","heading":"C. Pengurangan hingga 20","body":"Pengurangan hingga 20 dapat dilakukan dengan mengambil benda, menghitung mundur, atau mencapai sepuluh lebih dahulu. Jika 14 dikurangi 6, ambil empat untuk mencapai sepuluh, lalu ambil dua lagi. Kita sudah mengambil enam seluruhnya; sisanya delapan. Cara lain ialah mencari pasangan penjumlahan: enam ditambah berapa menjadi empat belas? Keduanya harus memberikan hasil yang sama. Periksa sisa dengan menjumlahkannya kembali dengan banyak yang diambil."},{"type":"text","heading":"Contoh bertahap 3","body":"Untuk 13 − 5, pisahkan 5 menjadi 3 dan 2. Dari 13 kurangi 3 menjadi 10, lalu kurangi 2 menjadi 8. Periksa 8 + 5 = 13. Pada soal cerita, jika ada tiga belas lembar dan lima dipakai, tersisa delapan lembar."},{"type":"tip","body":"Hitung 16 − 7 dengan benda. Coba pecah 7 menjadi 6 dan 1 untuk mencapai sepuluh dahulu. Periksa dengan penjumlahan."},{"type":"text","heading":"Kegiatan penerapan","body":"Bermain kartu strategi. Pendamping menyiapkan soal dalam rentang 20. Anak memilih satu soal dan menunjukkan dua cara, misalnya menggunakan benda dan membuat sepuluh. Pilih pula dua jumlah untuk mencari selisih. Setelah setiap jawaban, tanyakan “mengapa?” dan “bagaimana memeriksanya?”. Tidak perlu lomba kecepatan."},{"type":"text","heading":"Rangkuman bab","body":"Selisih adalah perbedaan dua jumlah. Penjumlahan dapat memakai pasangan untuk membuat sepuluh. Pengurangan dapat dipecah agar melewati sepuluh secara bertahap. Menggunakan benda dan operasi kebalikan membantu memeriksa hasil serta memahami artinya."},{"type":"text","heading":"Latihan mandiri","body":"1. Selisih 15 dan 12 adalah berapa?\n2. Hitung 8 + 5 dengan membuat sepuluh.\n3. Hitung 12 − 4.\n4. Ada 11 buku, datang 6 buku. Berapa semuanya?\n5. Ada 17 lembar kertas, dipakai 8. Berapa sisa dan bagaimana memeriksanya?"},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. 3, karena 15 − 12 = 3.\n2. 13. Pecah 5 menjadi 2 dan 3: 8 + 2 = 10 lalu 10 + 3 = 13.\n3. 8. Dari 12 ambil 2 menjadi 10 lalu 2 lagi menjadi 8.\n4. 17 buku; 11 + 6 = 17.\n5. Sisa 9 lembar. Periksa 9 + 8 = 17.","collapsible":true},{"type":"text","heading":"Refleksi belajar","body":"Tunjukkan satu hal yang sekarang dapat kamu lakukan. Jelaskan caranya memakai benda, gambar atau cerita. Bagian mana yang masih perlu bantuan? Kamu boleh kembali ke subbab tersebut sebelum lanjut. Pendamping mencatat cara berpikir dan bantuan yang masih diperlukan, bukan hanya banyak soal yang benar."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Jika membuat sepuluh membingungkan, gunakan bingkai sepuluh dan pindahkan benda secara nyata. Kembali ke pasangan bilangan bab 1 bila perlu. Pengayaan: bandingkan dua strategi untuk soal yang sama dan minta anak memilih cara yang mudah dijelaskan.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('6d1231c4-4a19-5cd0-930b-a491d4ac0d43','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Mengukur panjang','buku-matematika-kelas-1-bab-7',1,'A','Buku · Bab 7','dasar','draft',20,'{"summary":"Bab 7 dari 8 — Mengukur panjang. Bahan ajar berurutan dengan subbab, kegiatan, latihan dan pembahasan. Pelajari bertahap bersama pendamping.","video_url":null,"book_id":"matematika-1-2022","chapter_number":7,"content_kind":"full_chapter","cp_reference":{"document":"046/H/KR/2025","phase":"A","element_ids":["cp2025-matematika-a-3"],"mapping_status":"proposed_mapping","phase_coverage":"partial","reviewed_by":null},"review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal per bab, mengikuti urutan buku pemerintah 2022. Penulisan tersedia; ketepatan pedagogis dan keselarasan CP masih menunggu review guru.","objectives":["Membandingkan dan mengurutkan panjang dengan titik awal sejajar.","Mengukur panjang menggunakan satuan tidak baku yang sama.","Menjelaskan mengapa hasil ukur dapat berbeda jika satuannya berubah."],"enrichment":false,"curriculum_note":"Urutan bab mengikuti buku 2022; CP acuan proyek adalah 046/H/KR/2025. Kecukupan CP Fase A lintas kelas 1–2 tetap memerlukan pemetaan guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas I — Dara Retno Wulan dan Rasfaniwaty, 2022; hlm. cetak 197–218","url":"https://repositori.kemendikdasmen.go.id/35868/1/Matematika-BS-KLS-I.pdf#page=209","audience":"student"},{"title":"Buku panduan guru Matematika kelas I, 2022","url":"https://repositori.kemendikdasmen.go.id/35861/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Membandingkan dan mengurutkan panjang dengan titik awal sejajar.\n2. Mengukur panjang menggunakan satuan tidak baku yang sama.\n3. Menjelaskan mengapa hasil ukur dapat berbeda jika satuannya berubah."},{"type":"text","heading":"Sebelum mulai","body":"Panjang membantu menjelaskan ukuran suatu benda dari ujung ke ujung. Kita akan membandingkan langsung dan mengukur dengan benda satuan. Siapkan dua pita, pensil, potongan kartu sama panjang, dan tempat datar. Sentimeter belum menjadi alat utama bab ini; kita membangun pemahaman mengukur melalui satuan tidak baku terlebih dahulu."},{"type":"text","heading":"A. Membandingkan dan mengurutkan panjang","body":"Saat membandingkan dua benda, sejajarkan salah satu ujungnya. Amati ujung yang lain. Benda yang mencapai lebih jauh lebih panjang; yang ujungnya berhenti lebih dekat lebih pendek. Jika kedua ujung berimpit, panjangnya sama. Untuk tinggi benda, gunakan permukaan dasar yang sama. Posisi miring atau titik awal yang berbeda dapat membuat perbandingan tampak keliru. Mengurutkan beberapa benda dilakukan dari paling pendek ke paling panjang atau sebaliknya dengan aturan yang disebutkan."},{"type":"text","heading":"Contoh bertahap 1","body":"Letakkan pita biru dan pita putih dengan ujung kiri sejajar. Pita biru mencapai lebih jauh ke kanan, jadi lebih panjang. Jika pita putih digeser ke kanan, jangan langsung menyimpulkan ia lebih panjang; sejajarkan kembali titik awalnya."},{"type":"tip","body":"Bandingkan tiga pensil. Letakkan ujung awal sejajar, urutkan dari paling pendek, lalu ceritakan alasanmu. Jangan hanya melihat warna atau jarak letaknya."},{"type":"text","heading":"B. Mengukur dengan satuan tidak baku","body":"Mengukur berarti membandingkan panjang benda dengan satuan yang digunakan berulang. Gunakan potongan kartu yang sama panjang, letakkan berderet mulai dari ujung benda, rapat tanpa celah dan tidak bertumpuk. Hitung banyak satuan yang menutupi panjang benda. Jawaban menyebut bilangan dan satuannya, misalnya enam kartu. Untuk latihan awal pilih benda yang panjangnya tepat beberapa satuan. Jika ujung tidak pas, katakan masih ada bagian tersisa; jangan berpura-pura hasilnya tepat."},{"type":"text","heading":"Contoh bertahap 2","body":"Sebuah pita tepat sepanjang 8 potongan kartu yang sama. Kita menulis panjangnya 8 kartu. Bila dua kartu bertumpuk, hasil hitungan dapat menjadi terlalu banyak; jika ada celah, panjang yang dibandingkan tidak seluruhnya terwakili satuan."},{"type":"tip","body":"Ukur sisi buku dengan potongan kertas yang sama. Catat banyak satuan dan apakah ada bagian yang belum tertutup. Minta pendamping memeriksa letaknya."},{"type":"text","heading":"Kegiatan penerapan","body":"Menjadi petugas ukur meja. Pilih tiga benda aman yang dapat diletakkan datar. Gunakan satu jenis satuan yang sama untuk semuanya. Catat hasil, kemudian urutkan berdasarkan panjang. Ulangi pada satu benda memakai satuan yang lebih pendek. Bandingkan banyak satuannya: satuan lebih pendek biasanya perlu lebih banyak untuk panjang yang sama. Hasil hitungan tidak dapat dibandingkan adil jika satuannya berbeda."},{"type":"text","heading":"Rangkuman bab","body":"Perbandingan langsung memerlukan ujung awal atau dasar yang sama. Pengukuran menggunakan satuan berulang yang sama panjang, tanpa celah atau tumpukan. Hasil ukur menyebut bilangan dan satuan. Benda yang sama dapat mempunyai bilangan hasil ukur berbeda bila satuannya berubah."},{"type":"text","heading":"Latihan mandiri","body":"1. Mengapa ujung awal dua pita perlu disejajarkan?\n2. Pita A sepanjang 7 kartu, pita B 5 kartu yang sama. Mana lebih panjang?\n3. Bolehkah ada celah saat menyusun kartu satuan?\n4. Mengapa pengukuran dengan kartu pendek membutuhkan lebih banyak kartu?\n5. Ukur satu benda dan laporkan bilangan beserta satuannya."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Agar kedua panjang dibandingkan dari titik awal yang sama.\n2. Pita A; tujuh satuan yang sama lebih panjang daripada lima.\n3. Tidak; celah membuat satuan tidak menutupi panjang secara berurutan.\n4. Setiap kartu pendek menutupi bagian yang lebih kecil dari panjang benda yang sama.\n5. Jawaban sesuai pengukuran. Contoh: sisi kotak panjangnya 6 kartu; periksa kesamaan satuan dan letaknya.","collapsible":true},{"type":"text","heading":"Refleksi belajar","body":"Tunjukkan satu hal yang sekarang dapat kamu lakukan. Jelaskan caranya memakai benda, gambar atau cerita. Bagian mana yang masih perlu bantuan? Kamu boleh kembali ke subbab tersebut sebelum lanjut. Pendamping mencatat cara berpikir dan bantuan yang masih diperlukan, bukan hanya banyak soal yang benar."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Gunakan dua benda dahulu dan tandai titik awal dengan pita perekat. Jika anak membandingkan bilangan hasil ukur dari satuan berbeda, lakukan ulang dengan satu jenis satuan. Pengayaan: anak merancang petunjuk pengukuran agar orang lain dapat mengulang dengan hasil yang masuk akal.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
insert into public.lessons(id,subject_id,title,slug,grade,phase,chapter,difficulty,status,duration,content) values('185ff5ec-bd40-533b-be3a-33dae9542064','3b4e0049-f1bc-591b-91d6-cc32aad49ef3','Mengelompokkan data dan diagram gambar','buku-matematika-kelas-1-bab-8',1,'A','Buku · Bab 8','dasar','draft',20,'{"summary":"Bab 8 dari 8 — Mengelompokkan data dan diagram gambar. Bahan ajar berurutan dengan subbab, kegiatan, latihan dan pembahasan. Pelajari bertahap bersama pendamping.","video_url":null,"book_id":"matematika-1-2022","chapter_number":8,"content_kind":"full_chapter","cp_reference":{"document":"046/H/KR/2025","phase":"A","element_ids":["cp2025-matematika-a-5"],"mapping_status":"proposed_mapping","phase_coverage":"partial","reviewed_by":null},"review_status":"needs_teacher_review","editorial_notice":"Bahan ajar orisinal per bab, mengikuti urutan buku pemerintah 2022. Penulisan tersedia; ketepatan pedagogis dan keselarasan CP masih menunggu review guru.","objectives":["Mengelompokkan dan mencatat data sederhana.","Membaca diagram gambar dengan satu gambar mewakili satu benda atau satu pilihan.","Membandingkan kategori dan menjawab pertanyaan berdasarkan data."],"enrichment":false,"curriculum_note":"Urutan bab mengikuti buku 2022; CP acuan proyek adalah 046/H/KR/2025. Kecukupan CP Fase A lintas kelas 1–2 tetap memerlukan pemetaan guru.","source_refs":[{"title":"Matematika untuk SD/MI Kelas I — Dara Retno Wulan dan Rasfaniwaty, 2022; hlm. cetak 219–242","url":"https://repositori.kemendikdasmen.go.id/35868/1/Matematika-BS-KLS-I.pdf#page=231","audience":"student"},{"title":"Buku panduan guru Matematika kelas I, 2022","url":"https://repositori.kemendikdasmen.go.id/35861/","audience":"teacher"}],"blocks":[{"type":"text","heading":"Tujuan dan bekal awal","body":"1. Mengelompokkan dan mencatat data sederhana.\n2. Membaca diagram gambar dengan satu gambar mewakili satu benda atau satu pilihan.\n3. Membandingkan kategori dan menjawab pertanyaan berdasarkan data."},{"type":"text","heading":"Sebelum mulai","body":"Kita dapat mencari jawaban dari informasi yang dikumpulkan. Informasi itu disebut data. Misalnya, kita ingin mengetahui bentuk potongan kertas yang paling banyak dalam satu kotak. Setelah mengelompokkan dan mencatat, data dapat disajikan dengan gambar agar mudah dibaca. Kita memakai paling banyak empat kelompok dan satu gambar mewakili satu benda."},{"type":"text","heading":"A. Mengelompokkan data","body":"Mulai dari pertanyaan yang jelas. Tentukan apa yang akan dihitung dan aturan kelompoknya. Setiap benda atau pilihan dicatat sekali agar tidak terhitung ganda. Jika pertanyaannya tentang bentuk, buat kelompok lingkaran, segitiga, dan persegi. Nama kelompok membantu orang lain memahami catatan. Setelah mengelompokkan, hitung jumlah tiap kelompok dan periksa jumlah seluruhnya sama dengan banyak benda semula. Untuk pilihan teman, tanyakan satu pilihan per orang apabila itulah aturan pengumpulan datanya."},{"type":"text","heading":"Contoh bertahap 1","body":"Di satu kotak ada 4 lingkaran, 2 segitiga, dan 3 persegi. Catat tiga kelompok itu. Jumlah seluruh potongan adalah 4 + 2 + 3 = 9. Jika hitungan awal kotak berisi sembilan potongan, catatan tersebut cocok."},{"type":"tip","body":"Kumpulkan sepuluh potongan dalam tiga bentuk. Kelompokkan dan catat banyak tiap bentuk. Periksa apakah jumlah semua kelompok tepat sepuluh."},{"type":"text","heading":"B. Membaca dan membuat diagram gambar","body":"Diagram gambar menyajikan banyaknya data menggunakan gambar atau tanda yang seragam. Tuliskan judul, nama kelompok, dan keterangan arti gambar. Pada bab ini, satu gambar berarti satu benda atau satu pilihan. Susun gambar mulai dari garis awal yang sejajar dan gunakan jarak yang serupa. Kelompok dengan gambar paling banyak mempunyai jumlah paling besar. Kelompok tanpa gambar bernilai nol jika keterangan dan nama kelompoknya tetap ditampilkan. Jangan menilai jumlah hanya dari besar gambar; hitung tanda satu per satu."},{"type":"text","heading":"Contoh bertahap 2","body":"Judul diagram: “Potongan Bentuk dalam Kotak”. Keterangan: satu ● mewakili satu potongan. Lingkaran: ● ● ● ●; segitiga: ● ●; persegi: ● ● ●. Lingkaran paling banyak, segitiga paling sedikit. Selisih lingkaran dan segitiga adalah dua. Diagram hanya menjelaskan kotak yang diamati, bukan semua kotak di rumah."},{"type":"tip","body":"Buat diagram dari catatanmu. Gunakan satu tanda untuk satu potongan. Tulis dua pertanyaan yang jawabannya dapat ditemukan pada diagram, lalu minta pendamping menjawab."},{"type":"text","heading":"Kegiatan penerapan","body":"Survei pilihan bacaan keluarga. Siapkan tiga pilihan yang jelas, misalnya cerita hewan, cerita perjalanan, dan informasi alam. Setiap anggota yang bersedia memilih satu. Tidak perlu menuliskan nama atau informasi pribadi. Catat jumlah tiap pilihan dan buat diagram satu tanda satu pilihan. Jelaskan jumlah peserta, pilihan paling banyak, dan selisih dua kelompok. Jika ada hasil sama, katakan sama banyak; tidak perlu memaksa ada pemenang."},{"type":"text","heading":"Rangkuman bab","body":"Data dikumpulkan untuk menjawab pertanyaan. Kelompok harus jelas dan pencatatan tidak boleh ganda. Diagram gambar memerlukan judul, nama kategori dan keterangan nilai gambar. Perbandingan, selisih dan jumlah seluruh data dibaca dari tanda yang sesuai. Kesimpulan dibatasi pada data yang benar-benar dikumpulkan."},{"type":"text","heading":"Latihan mandiri","body":"Gunakan catatan: apel 5, pisang 3, jeruk 2.\n1. Ada berapa kategori buah?\n2. Buah mana paling banyak?\n3. Berapa jumlah seluruh buah?\n4. Berapa selisih apel dan jeruk?\n5. Buat diagram dengan satu tanda mewakili satu buah."},{"type":"text","heading":"Pembahasan latihan mandiri","body":"1. Tiga kategori: apel, pisang dan jeruk.\n2. Apel, karena jumlahnya lima dan paling besar.\n3. 10 buah; 5 + 3 + 2 = 10.\n4. 3 buah; 5 − 2 = 3.\n5. Buat lima tanda untuk apel, tiga untuk pisang dan dua untuk jeruk; sertakan judul serta keterangan satu tanda satu buah.","collapsible":true},{"type":"text","heading":"Refleksi belajar","body":"Tunjukkan satu hal yang sekarang dapat kamu lakukan. Jelaskan caranya memakai benda, gambar atau cerita. Bagian mana yang masih perlu bantuan? Kamu boleh kembali ke subbab tersebut sebelum lanjut. Pendamping mencatat cara berpikir dan bantuan yang masih diperlukan, bukan hanya banyak soal yang benar."},{"type":"text","heading":"Catatan pendamping: bantuan dan pengayaan","body":"Mulai dengan dua kategori dan data benda nyata jika diagram masih sulit dipahami. Biarkan anak memindahkan satu benda menjadi satu tanda gambar. Pengayaan: berikan dua kategori yang sama banyak dan tanyakan bagaimana menyampaikan kesimpulannya tanpa menambah atau mengubah data.","collapsible":true}]}'::jsonb) on conflict(id) do nothing;
